package com.gymmind.membership.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.membership.domain.model.Order; import com.gymmind.membership.domain.repository.OrderRepository; import com.gymmind.shared.security.CurrentActor; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.Set; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class OrderServiceTest{@Test void createOrderUsesActorTenant(){OrderRepository orders=mock(OrderRepository.class);when(orders.save(any(Order.class))).thenAnswer(i->i.getArgument(0));DefaultOrderService service=new DefaultOrderService(orders,mock(AuditRecorder.class));OrderView v=service.create(admin(11L),new CreateOrderCommand(null,41L,new BigDecimal("99"),"CNY"));assertThat(v.tenantId()).isEqualTo(11L);assertThat(v.memberId()).isEqualTo(41L);}private static CurrentActor admin(long t){return new CurrentActor(1L,t,Set.of(RoleCode.GYM_ADMIN),Set.of("order:write"),0L,"token");}}
